SELECT
    DATA,
    nvl(DATA:policyDetails.policyNumber::STRING, 'null') AS policy_number,
    nvl(DATA:policyDetails.quotationNumber::STRING, 'null') AS quotation_number,
    COUNT(DATA),
    COUNT(FILE_NAME) AS file_count,
    COUNT(DISTINCT FILE_NAME) AS distinct_file_names,
    LISTAGG(FILE_NAME, ', ') AS file_names,
    LISTAGG(FILE_TIMESTAMP, ', ') s3_file_timestamp
FROM BAGIC_PROD_STAGING_DB.MAXI_RAW.NONHLTH_TRV_UWR
WHERE policy_number = 'null' and quotation_number != 'null'
group by DATA
HAVING COUNT(*) > 1

